    os.write(Packages.java.lang.String(String(body)).getBytes('UTF-8'));
    os.flush(); os.close();
  }
  // 先取状态码（需要它判断 503/401），再读正文；两条信息来自同一响应
  var code=0, txt='';
  try{ code=conn.getResponseCode(); }catch(e1){ code=-1; }
  var is=null;
  try{ is=conn.getInputStream(); }
  catch(e2){ try{ is=conn.getErrorStream(); }catch(e3){ is=null; } }
  if(is){
    try{
      var br=new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(is,'UTF-8'));
      var sb=new Packages.java.lang.StringBuilder();
      var ln=br.readLine();
