function loginAction(action, state, form){
  var st={};
  try{ st=(typeof state==='string')?JSON.parse(state):(state||{}); }catch(e){ st={}; }
  var a=String(action||'');

  if(a.indexOf('use:')===0){
    var host=a.slice(4);
    kjlPut('kj_host',host);
    return JSON.stringify({state:{cur:host,res:st.res||null,who:kjlWhoami(),
      note:'已切换到 '+host.replace('https://','')+'。若仍播不了，点「🚀 测速并登录」。'}});
  }

  if(a==='logout'){
    kjlDel('kj_sess');
    return JSON.stringify({state:{cur:kjlCurHost(),res:st.res||null,who:kjlWhoami(),
      note:'已清除本机会话（官方高清线路将无法换票）。'}});
  }

  if(a==='login'){
    var h0=kjlCurHost();
    var r=kjlTryLogin(h0);
    if(r.ok){
      kjlPut('kj_sess',r.cookie);
      return JSON.stringify({state:{cur:h0,res:st.res||null,who:kjlWhoami(),
        note:'✅ 登录成功'+(r.name?('（'+r.name+'）'):'')+'，官方高清线路已解锁。'}});
    }
    return JSON.stringify({state:{cur:h0,res:st.res||null,who:kjlWhoami(),
      note:'❌ '+h0.replace('https://','')+' 登录失败（'+r.msg+'）。请点「🚀 测速并登录」自动换线。'}});
  }

  if(a==='auto'){
    var order=[],i;
    // 先测速，按快的优先
    var results=[];
    for(i=0;i<KJ_DOMAINS.length;i++){
      var h=KJ_DOMAINS[i];
      var ms=kjlPing(h,6000);
      results.push({h:h,ms:ms,best:false});
    }
    results.sort(function(x,y){
      if(x.ms<0&&y.ms<0){ return 0; }
      if(x.ms<0){ return 1; }
      if(y.ms<0){ return -1; }
      return x.ms-y.ms;
    });
    if(results.length&&results[0].ms>=0){ results[0].best=true; }
    // 按测速顺序尝试登录
    var tries=[], okHost='', okCk='', okName='';
    for(i=0;i<results.length;i++){
      if(results[i].ms<0){ continue; }               // 测速就不通的跳过
      var rr=kjlTryLogin(results[i].h);
      tries.push(results[i].h.replace('https://','')+(rr.ok?'✅':'✖'));
      if(rr.ok){ okHost=results[i].h; okCk=rr.cookie; okName=rr.name; break; }
    }
    if(!okHost){
      return JSON.stringify({state:{cur:kjlCurHost(),res:results,who:kjlWhoami(),
        note:'❌ 没有可用线路（已尝试 '+tries.join(' ')+'）。可能站点全线维护，请稍后再试。'}});
    }
    kjlPut('kj_host',okHost);
    kjlPut('kj_sess',okCk);
    return JSON.stringify({state:{cur:okHost,res:results,who:kjlWhoami(),
      note:'✅ 已自动选线并登录：'+okHost.replace('https://','')+(okName?('（'+okName+'）'):'')+'\n尝试顺序：'+tries.join(' ')+'\n官方高清线路已解锁。'}});
  }

  if(a==='ping'){
    var out=[],best=-1,bh='';
    for(var k=0;k<KJ_DOMAINS.length;k++){
      var hh=KJ_DOMAINS[k];
      var ms2=kjlPing(hh,6000);
      out.push({h:hh,ms:ms2,best:false});
      if(ms2>=0&&(best<0||ms2<best)){ best=ms2; bh=hh; }
    }
    for(var q=0;q<out.length;q++){ if(out[q].h===bh){ out[q].best=true; } }
    out.sort(function(x,y){
      if(x.ms<0&&y.ms<0){ return 0; }
      if(x.ms<0){ return 1; }
      if(y.ms<0){ return -1; }
      return x.ms-y.ms;
    });
    var note=bh?('最快：'+bh.replace('https://','')+'（'+best+' ms）。点它切换，或点「🚀 测速并登录」一步到位。')
                :'全部线路都不通，请检查网络或稍后再试。';
    return JSON.stringify({state:{cur:kjlCurHost(),res:out,who:kjlWhoami(),note:note}});
  }

  return JSON.stringify({state:st});
}


