// 背景：原 loginUi={"version":2} 是 V2 面板，E 版无 V2 delegate，GSON.fromJsonArray 解析失败→界面失效。
// 修法：loginUi 改 @js:kjV1Rows()（E 版 SourceLoginDialog.evalUiJs 走 source.evalJS(loginJS+'\n'+code)，
// source 绑定可用→可读线路变量；java 不注入 evalUiJs，故一切 java 操作放按钮 action，action 有 java 绑定）。
// 每次 java.reLoginView() 会重跑 kjV1Rows 重建面板，状态直接编码在按钮名上，无需 V2 的 state 对象。
function kjV1GV(k, def) {
  var v = '';
  try { v = String(source.get(k) || ''); } catch (e) {}
  if (!v || v === 'null' || v === 'undefined') v = def || '';
  return v;
}
function kjV1PV(k, v) { try { source.put(k, String(v)); } catch (e) {} }
function kjV1Rows() {
  var W1 = { layout_flexGrow: 1, layout_flexBasisPercent: 1 };
  var W2 = { layout_flexGrow: 1, layout_flexBasisPercent: 0.48 };
  var R = [];
  var cur = kjlCurHost();
  var whoOk = kjV1GV('kj_who_ok', '0') === '1';
  var whoMsg = kjV1GV('kj_who', '未登录（点此检查）');
  var note = kjV1GV('kj_note', '');
  var ping = kjV1GV('kj_ping', '');
  // 状态行用 button 承载（E 版 label 不渲染；button 两版都显示，点击=刷新对应状态）
  R.push({ name: '看剧AI · 线路与登录', type: 'button', action: 'kjV1Help(java)', style: W1 });
  R.push({ name: (whoOk ? '✅ ' : '⚠️ ') + whoMsg, type: 'button', action: 'kjV1Whoami(java)', style: W1 });
  R.push({ name: '当前：' + cur.replace('https://', '') + (ping ? ('  ' + ping) : ''), type: 'button', action: 'kjV1Ping(java)', style: W1 });
  R.push({ name: '🚀 测速并登录（推荐）', type: 'button', action: 'kjV1Auto(java)', style: W1 });
  R.push({ name: '🔑 当前线路登录', type: 'button', action: 'kjV1Login(java)', style: W2 });
  R.push({ name: '🚪 退出登录', type: 'button', action: 'kjV1Logout(java)', style: W2 });
  var msMap = {};
  try { msMap = JSON.parse(kjV1GV('kj_ping_map', '{}')); } catch (e) {}
  var best = kjV1GV('kj_best', '');
  for (var i = 0; i < KJ_DOMAINS.length; i++) {
    var h = KJ_DOMAINS[i];
    var mk = (h === cur ? ' ✅' : '');
    if (msMap[h] !== undefined) mk = (msMap[h] >= 0 ? ' ' + msMap[h] + 'ms' : ' ✖') + (h === best ? '⭐' : '');
    R.push({ name: h.replace('https://', '') + mk, type: 'button', action: "kjV1Use(java,'" + h + "')", style: W2 });
  }
  R.push({ name: '🔍 仅测速（不登录）', type: 'button', action: 'kjV1Ping(java)', style: W1 });
  if (note) R.push({ name: String(note), type: 'button', action: 'kjV1Help(java)', style: W1 });
  return JSON.stringify(R);
}
function kjV1Refresh(jv, msg) {
  if (msg) kjV1PV('kj_note', msg);
  try { jv.longToast(String(msg || '')); } catch (e) { try { jv.toast(String(msg || '')); } catch (e2) {} }
  try { jv.reLoginView(true); } catch (e3) { try { jv.reUiView(true); } catch (e4) {} }
  return 'ok';
}
function kjV1Help(jv) {
  return kjV1Refresh(jv, '选线路→登录；官方高清线路需先登录换票。「测速并登录」一步到位。');
}
function kjV1Use(jv, host) {
  kjlPut('kj_host', host);
  kjV1PV('kj_who_ok', '0'); kjV1PV('kj_who', '未登录（点此检查）');
  return kjV1Refresh(jv, '已切换到 ' + String(host).replace('https://', '') + '，点「测速并登录」生效。');
}
function kjV1Logout(jv) {
  kjlDel('kj_sess');
  kjV1PV('kj_who_ok', '0'); kjV1PV('kj_who', '未登录（点此检查）');
  return kjV1Refresh(jv, '已清除本机会话。');
}
function kjV1Whoami(jv) {
  var w = kjlWhoami();
  kjV1PV('kj_who_ok', w.ok ? '1' : '0'); kjV1PV('kj_who', String(w.msg || ''));
  return kjV1Refresh(jv, (w.ok ? '✅ ' : '⚠️ ') + w.msg);
}
function kjV1Login(jv) {
  var h0 = kjlCurHost();
  var r = kjlTryLogin(h0);
  if (r.ok) {
    kjlPut('kj_sess', r.cookie);
    var w = kjlWhoami();
    kjV1PV('kj_who_ok', w.ok ? '1' : '0'); kjV1PV('kj_who', String(w.msg || ''));
    return kjV1Refresh(jv, '✅ 登录成功' + (r.name ? ('(' + r.name + ')') : '') + ' · ' + h0.replace('https://', ''));
  }
  return kjV1Refresh(jv, '❌ ' + h0.replace('https://', '') + ' 登录失败(' + r.msg + ')，请点「测速并登录」。');
}
function kjV1Ping(jv) {
  var map = {}, bestMs = -1, bestH = '', i, h, ms, lines = [];
  for (i = 0; i < KJ_DOMAINS.length; i++) {
    h = KJ_DOMAINS[i];
    ms = kjlPing(h, 6000);
    map[h] = ms;
    lines.push(h.replace('https://', '') + (ms >= 0 ? (ms + 'ms') : '✖'));
    if (ms >= 0 && (bestMs < 0 || ms < bestMs)) { bestMs = ms; bestH = h; }
  }
  kjV1PV('kj_ping_map', JSON.stringify(map));
  kjV1PV('kj_ping', bestH ? ('最快 ' + bestH.replace('https://', '') + ' ' + bestMs + 'ms') : '全部不通');
  if (bestH) kjV1PV('kj_best', bestH);
  return kjV1Refresh(jv, '测速：' + lines.join(' / '));
}
function kjV1Auto(jv) {
  var map = {}, results = [], i, h, ms;
  for (i = 0; i < KJ_DOMAINS.length; i++) {
    h = KJ_DOMAINS[i];
    ms = kjlPing(h, 6000);
    map[h] = ms; results.push({ h: h, ms: ms });
  }
  results.sort(function (a, b) {
    if (a.ms < 0 && b.ms < 0) return 0;
    if (a.ms < 0) return 1;
    if (b.ms < 0) return -1;
    return a.ms - b.ms;
  });
  kjV1PV('kj_ping_map', JSON.stringify(map));
  if (results.length && results[0].ms >= 0) kjV1PV('kj_best', results[0].h);
  var tries = [], okHost = '', okCk = '', okName = '';
  for (i = 0; i < results.length; i++) {
    if (results[i].ms < 0) continue;
    var rr = kjlTryLogin(results[i].h);
    tries.push(results[i].h.replace('https://', '') + (rr.ok ? '✅' : '✖'));
    if (rr.ok) { okHost = results[i].h; okCk = rr.cookie; okName = rr.name; break; }
  }
  if (!okHost) return kjV1Refresh(jv, '❌ 无可用线路：' + tries.join(' '));
  kjlPut('kj_host', okHost); kjlPut('kj_sess', okCk);
  kjV1PV('kj_ping', '已选 ' + okHost.replace('https://', '') + ' ' + results[0].ms + 'ms');
  var w = kjlWhoami();
  kjV1PV('kj_who_ok', w.ok ? '1' : '0'); kjV1PV('kj_who', String(w.msg || ''));
  return kjV1Refresh(jv, '✅ 已选线登录 ' + okHost.replace('https://', '') + (okName ? ('(' + okName + ')') : '') + '\n' + tries.join(' '));
}
